import { useState } from 'react'
import { Document, Page, pdfjs } from 'react-pdf'
import '@react-pdf-viewer/core/lib/styles/index.css'
pdfjs.GlobalWorkerOptions.workerSrc = `//unpkg.com/pdfjs-dist@${pdfjs.version}/legacy/build/pdf.worker.min.js`

function Documents (props) {
  const id = props.match.params.id
  const objectMapping = {
    'Ringkasan-Produk-PA-SAFETRIP-PREMIUM-AUS-290724_240730_134327.pdf': 'https://pp-img-prod.s3.ap-southeast-3.amazonaws.com/gojek/public-files/Ringkasan-Produk-PA-SAFETRIP+PREMIUM+-+Compiled_270726.pdf'
  }

  const [numPages, setNumPages] = useState(null)

  const onDocumentLoadSuccess = ({ numPages }) => {
    setNumPages(numPages)
  }

  return (
    <div>
      <Document
        file={{ url: objectMapping[id] }}
        onLoadSuccess={onDocumentLoadSuccess}
      >
        {
          Array.from(new Array(numPages), (el, index) => (
            <Page
              width={window.innerWidth}
              key={`page_${index + 1}`}
              pageNumber={index + 1}
              className='document-card-item-pdf'
              renderTextLayer={false}
            />
          ))
        }
      </Document>
    </div>
  )
}

export default Documents
